import assert from "node:assert/strict";
import { inspect } from "./instance.mjs";
import { checkUsersUI } from "./users-ui-checks.mjs";
import { usersUI } from "./users-ui-support.mjs";
import { verifyUsersAccess } from "./users-access-ui.mjs";
import { addJellyfinUser } from "./run-jellyfin.mjs";

export async function verifyUsersUI(run, owner) {
  const ui = usersUI(run);
  const { expect, record, save, api, open, signIn, directory, details, checkAxe, checkTrap, provider, steps, requests, errors, contexts } = ui;
  try {
    const admin = await open(1440);
    await signIn(admin, owner.username, owner.password, "users");
    await directory(admin.page); await save(admin.page, "owner-before-1440");
    const created = {};
    for (const name of ["UI Member", "UI Admin", "UI Other"]) created[name] = await addJellyfinUser(run, name);
    await admin.page.getByRole("button", { name: "Import Jellyfin users", exact: true }).click();
    let importing = admin.page.getByRole("dialog", { name: "Import Jellyfin users", exact: true });
    for (const name of Object.keys(created)) await importing.getByRole("checkbox", { name, exact: true }).check();
    await checkTrap(admin.page, importing); await importing.getByRole("button", { name: "Import selected", exact: true }).click();
    for (const name of Object.keys(created)) await expect(importing.getByRole("region", { name: "Import results" })).toContainText(`${name}: imported`);
    await importing.getByRole("button", { name: "Close", exact: true }).click(); await expect(importing).toHaveCount(0);
    const listing = await api(admin.context, "GET", "/api/users");
    run.write("ui-created-accounts.json", listing.items.map(({ id, username, display_name, source, role, status }) => ({ id, username, display_name, source, role, status })));
    for (const name of Object.keys(created)) {
      await expect(admin.page.getByRole("button", { name: `View ${name}`, exact: true })).toBeVisible();
      created[name].account = listing.items.find(entry => entry.display_name === name);
      assert.deepEqual([created[name].account?.source, created[name].account?.role, created[name].account?.status], ["jellyfin", "user", "active"]);
    }
    assert.equal(await admin.page.getByRole("button", { name: "Create local account", exact: true }).count(), 0, "Users offers no local account creation");
    record("owner imports three ordinary Jellyfin users through UI, offers no local account creation, and independent GET confirms persistence");
    await api(admin.context, "PUT", `/api/users/${created["UI Admin"].account.id}/role`, { role: "admin", reauthentication: { password: owner.password } });
    const member = await open(1440), memberPassword = created["UI Member"].password;
    await signIn(member, "UI Member", memberPassword); await expect(member.page.getByRole("heading", { name: "My profile", exact: true })).toBeVisible();
    const beforeDenied = requests.length;
    await member.page.goto(`${run.manifest.origin}/#/settings/users`);
    await expect(member.page.getByRole("heading", { name: "Page unavailable" })).toBeVisible();
    assert.equal(await member.page.getByRole("button", { name: "Users", exact: true }).count(), 0);
    assert.equal(requests.slice(beforeDenied).filter(request => request.path === "/api/users").length, 0);
    await api(member.context, "GET", "/api/users", undefined, 403);
    record("ordinary directory deep link mounts no directory, sends no search, and direct API is refused");
    await member.page.goto(`${run.manifest.origin}/#/settings/profile`);
    await expect(member.page.getByText("Avatar from Jellyfin", { exact: true })).toBeVisible();
    assert.equal(await member.page.getByLabel("Display name", { exact: true }).count(), 0); assert.equal(await member.page.getByLabel("Avatar image").count(), 0);
    await member.page.getByLabel("Email", { exact: true }).fill("member@example.test");
    await member.page.getByLabel("Timezone", { exact: true }).fill("Europe/Paris");
    await member.page.getByRole("button", { name: "Save profile", exact: true }).click();
    await expect(member.page.getByText("Profile saved.", { exact: true })).toBeVisible();
    const profile = await api(member.context, "GET", `/api/users/${created["UI Member"].account.id}`);
    assert.deepEqual([profile.display_name, profile.email, profile.timezone, profile.language], ["UI Member", "member@example.test", "Europe/Paris", "en"]);
    await member.page.reload(); await expect(member.page.getByLabel("Email", { exact: true })).toHaveValue("member@example.test");
    await save(member.page, "member-profile-1440"); await checkAxe(member.page, "member-profile-1440");
    record("ordinary profile email, timezone and English preference persist after reload; Jellyfin keeps the name and avatar");
    await member.page.getByRole("button", { name: "Generate API key", exact: true }).click();
    let proof = member.page.getByRole("dialog", { name: "Generate API key?", exact: true });
    await proof.getByLabel("Jellyfin password").fill("wrong synthetic proof"); await proof.getByRole("button", { name: "Generate key", exact: true }).click();
    await expect(proof.getByRole("alert")).toBeVisible(); await expect(proof.getByLabel("Jellyfin password")).toHaveValue("");
    await proof.getByLabel("Jellyfin password").fill(memberPassword); await proof.getByRole("button", { name: "Generate key", exact: true }).click();
    await expect(member.page.getByLabel("Current API key", { exact: true })).toBeVisible();
    const apiKey = await member.page.getByLabel("Current API key", { exact: true }).inputValue(); run.secrets.add(apiKey);
    await save(member.page, "member-key-masked-1440"); await member.page.getByRole("button", { name: "Hide key", exact: true }).click();
    record("API-key creation requires successful fresh proof and screenshots mask the revealed key");
    const secondAdmin = await open(1440), adminPassword = created["UI Admin"].password;
    await signIn(secondAdmin, "UI Admin", adminPassword, "users"); await directory(secondAdmin.page);
    assert.equal(await secondAdmin.page.getByLabel("Local registration").count(), 0);
    assert.equal(await secondAdmin.page.getByLabel("Jellyfin admission").count(), 0);
    let dialog = await details(secondAdmin.page, owner.username);
    for (const name of ["Disable account", "Reset password", "Revoke sessions", "Save profile", "Revoke API key"]) assert.equal(await dialog.getByRole("button", { name, exact: true }).count(), 0);
    await dialog.getByRole("button", { name: "Close", exact: true }).click();
    dialog = await details(secondAdmin.page, "UI Member");
    assert.equal(await dialog.getByRole("button", { name: "Show API key", exact: true }).count(), 0);
    assert.equal(await dialog.getByRole("button", { name: "Generate new API key", exact: true }).count(), 0);
    await expect(dialog.getByRole("button", { name: "Revoke API key", exact: true })).toBeVisible();
    await dialog.getByLabel("Email", { exact: true }).fill("edited@example.test"); await dialog.getByRole("button", { name: "Save profile", exact: true }).click();
    await expect(dialog.getByText("Profile saved.", { exact: true })).toBeVisible();
    await dialog.getByRole("button", { name: "Revoke sessions", exact: true }).click();
    let confirm = secondAdmin.page.getByRole("dialog", { name: "Revoke sessions?", exact: true }); await checkTrap(secondAdmin.page, confirm);
    await confirm.getByRole("button", { name: "Confirm", exact: true }).click();
    await expect(dialog.getByText(/browser sessions revoked/)).toBeVisible();
    assert.equal((await member.context.request.get(run.manifest.origin + "/api/system/version", { headers: { "X-Api-Key": apiKey } })).status(), 200);
    await member.page.reload(); await expect(member.page.getByRole("heading", { name: "SIGN IN TO CONTINUE" })).toBeVisible();
    record("admin edits ordinary profiles and revokes their browser sessions, cannot reveal keys or manage owner, and key survives");
    await dialog.getByRole("button", { name: "Disable account", exact: true }).click();
    confirm = secondAdmin.page.getByRole("dialog", { name: "Disable account?", exact: true }); await confirm.getByRole("button", { name: "Confirm", exact: true }).click();
    await expect(dialog.getByText("Account disabled. Data retained.", { exact: true })).toBeVisible();
    assert.equal((await api(secondAdmin.context, "GET", `/api/users/${profile.id}`)).status, "disabled");
    await dialog.getByRole("button", { name: "Enable account", exact: true }).click();
    await secondAdmin.page.getByRole("dialog", { name: "Enable account?", exact: true }).getByRole("button", { name: "Confirm", exact: true }).click();
    await expect(dialog.getByText("Account enabled.", { exact: true })).toBeVisible(); await dialog.getByRole("button", { name: "Close", exact: true }).click();
    record("admin disable/enable of a linked account persists without deleting data");
    await directory(admin.page);
    for (const label of ["Local registration", "Jellyfin admission"]) assert.equal(await admin.page.getByLabel(label).count(), 0, `Users has no ${label} control`);
    await api(admin.context, "GET", "/api/settings/registration", undefined, 404);
    await api(admin.context, "GET", "/api/settings/jellyfin-admission", undefined, 404);
    record("owner finds no registration or Jellyfin admission mode in the UI or API");
    const jf = await provider(); await api(admin.context, "PUT", "/api/settings/jellyfin", { server_url: jf.base, api_key: jf.key });
    await directory(admin.page); await admin.page.getByRole("button", { name: "Import Jellyfin users", exact: true }).click();
    importing = admin.page.getByRole("dialog", { name: "Import Jellyfin users", exact: true });
    await importing.getByRole("checkbox", { name: "jf-linked", exact: true }).check(); await importing.getByRole("button", { name: "Import selected", exact: true }).click();
    await expect(importing.getByRole("region", { name: "Import results" })).toContainText("jf-linked: imported");
    await importing.getByRole("button", { name: "Import all", exact: true }).click();
    const all = admin.page.getByRole("dialog", { name: "Import all Jellyfin users?", exact: true }); await checkTrap(admin.page, all); await all.getByRole("button", { name: "Confirm import all", exact: true }).click();
    await expect(importing.getByRole("region", { name: "Import results" })).toContainText("jf-linked: existing");
    await expect(importing.getByRole("region", { name: "Import results" })).toContainText("jf-second: imported");
    await importing.getByRole("button", { name: "Close", exact: true }).click();
    await directory(secondAdmin.page); await secondAdmin.page.getByRole("button", { name: "Sync Jellyfin now", exact: true }).click();
    await expect(secondAdmin.page.getByRole("region", { name: "Sync results" })).toContainText("jf-linked: verified");
    const sync = await api(secondAdmin.context, "GET", "/api/jellyfin/sync"); assert.ok(sync.accounts.every(entry => entry.last_verified_at));
    record("live Jellyfin selected/all imports show per-user outcomes and admin sync shows last successful verification");
    const linked = await open(1440); await signIn(linked, "jf-linked", jf.linkedPassword);
    await expect(linked.page.getByRole("heading", { name: "My profile", exact: true })).toBeVisible();
    assert.equal(await linked.page.getByLabel("Display name", { exact: true }).count(), 0); assert.equal(await linked.page.getByLabel("Avatar image").count(), 0);
    await expect(linked.page.getByText("Avatar from Jellyfin", { exact: true })).toBeVisible();
    await linked.page.getByLabel("Email", { exact: true }).fill("linked@example.test"); await linked.page.getByLabel("Timezone", { exact: true }).fill("UTC");
    await linked.page.getByRole("button", { name: "Save profile", exact: true }).click(); await expect(linked.page.getByText("Profile saved.", { exact: true })).toBeVisible();
    await linked.page.reload(); await expect(linked.page.getByLabel("Email", { exact: true })).toHaveValue("linked@example.test");
    await save(linked.page, "linked-profile-1440"); await checkAxe(linked.page, "linked-profile-1440");
    record("linked name and avatar are read-only while local email/timezone preferences persist");
    let lastMember;
    for (const width of [1440, 320]) {
      await admin.page.setViewportSize({ width, height: 900 }); await directory(admin.page);
      await save(admin.page, `owner-directory-${width}`); await checkAxe(admin.page, `owner-directory-${width}`);
      await admin.page.getByRole("searchbox", { name: "Search users" }).fill("UI"); await admin.page.getByRole("button", { name: "Search", exact: true }).click();
      await expect(admin.page.getByRole("button", { name: "View UI Other", exact: true })).toBeVisible();
      await admin.page.getByRole("checkbox", { name: "Select UI Other", exact: true }).check(); await admin.page.getByRole("button", { name: "Disable selected", exact: true }).click();
      confirm = admin.page.getByRole("dialog", { name: "Disable selected accounts?", exact: true }); await checkTrap(admin.page, confirm); await save(admin.page, `bulk-confirm-${width}`); await confirm.getByRole("button", { name: "Confirm", exact: true }).click();
      await expect(admin.page.getByRole("region", { name: "Bulk results" })).toContainText("UI Other: applied");
      assert.equal((await api(admin.context, "GET", `/api/users/${created["UI Other"].account.id}`)).status, "disabled");
      dialog = await details(admin.page, "UI Other"); await checkTrap(admin.page, dialog); await save(admin.page, `account-dialog-${width}`); await checkAxe(admin.page, `account-dialog-${width}`);
      await admin.page.keyboard.press("Escape"); await expect(dialog).toHaveCount(0); await expect(admin.page.getByRole("button", { name: "View UI Other", exact: true })).toBeFocused();
      await admin.page.getByRole("checkbox", { name: "Select UI Other", exact: true }).check(); await admin.page.getByRole("button", { name: "Enable selected", exact: true }).click();
      const enableDialog = admin.page.getByRole("dialog", { name: "Enable selected accounts?", exact: true });
      const enabled = admin.page.waitForResponse(response => response.request().method() === "POST" && new URL(response.url()).pathname === "/api/users/bulk" && response.request().postDataJSON()?.action === "enable");
      await enableDialog.getByRole("button", { name: "Confirm", exact: true }).click();
      const enableResponse = await enabled;
      assert.equal(enableResponse.status(), 200, "bulk enable request");
      assert.equal((await enableResponse.json()).results.find(result => result.user_id === created["UI Other"].account.id)?.outcome, "applied", "bulk enable outcome for UI Other");
      await expect(enableDialog).toHaveCount(0);
      await expect(admin.page.getByRole("region", { name: "Bulk results" })).toContainText("UI Other: applied");
      assert.equal((await api(admin.context, "GET", `/api/users/${created["UI Other"].account.id}`)).status, "active");
      const freshMember = await open(width); lastMember = freshMember;
      await signIn(freshMember, "UI Member", memberPassword); await expect(freshMember.page.getByLabel("Email", { exact: true })).toHaveValue("edited@example.test");
      await expect(freshMember.page.getByRole("button", { name: "Show API key", exact: true })).toBeVisible(); assert.equal(await freshMember.page.getByLabel("Current API key", { exact: true }).count(), 0);
      await save(freshMember.page, `fresh-member-profile-${width}`); await checkAxe(freshMember.page, `fresh-member-profile-${width}`);
      record(`${width}px directory, search, bulk, account dialog, focus trap/Escape restoration, axe and fresh persisted user profile pass`);
    }
    await directory(admin.page); dialog = await details(admin.page, "UI Member");
    await dialog.getByRole("button", { name: "Show API key", exact: true }).click(); proof = admin.page.getByRole("dialog", { name: "Show API key?", exact: true });
    await checkTrap(admin.page, proof); await proof.getByLabel(/^(?:Current|Jellyfin) password$/).fill(owner.password); await proof.getByRole("button", { name: "Show key", exact: true }).click();
    await expect(dialog.getByLabel("Current API key", { exact: true })).toBeVisible(); assert.equal(await dialog.getByLabel("Current API key", { exact: true }).inputValue(), apiKey);
    await save(admin.page, "owner-target-key-masked-320"); await dialog.getByRole("button", { name: "Close", exact: true }).click();
    assert.equal(await admin.page.getByLabel("Current API key", { exact: true }).count(), 0);
    record("owner target-key reveal requires fresh proof and its nested dialog traps keyboard focus at 320px");
    await secondAdmin.page.setViewportSize({ width: 320, height: 900 }); await directory(secondAdmin.page);
    assert.equal(await secondAdmin.page.getByLabel("Local registration").count(), 0); assert.equal(await secondAdmin.page.getByLabel("Jellyfin admission").count(), 0);
    await save(secondAdmin.page, "admin-directory-320"); await checkAxe(secondAdmin.page, "admin-directory-320");
    record("admin directory remains usable at 320px without admission controls");
    assert.equal(await lastMember.page.locator(".security-form").count(), 0, "the profile offers no local username or password change");
    assert.ok((await lastMember.context.request.get(run.manifest.origin + "/api/system/version", { headers: { "X-Api-Key": apiKey } })).ok());
    await save(lastMember.page, "member-security-after-320");
    record("the member's profile offers no local username or password change and its API key still works");
    await checkUsersUI({ ...ui, admin, secondAdmin, lastMember, linked, jf });
    assert.deepEqual(errors, []); assert.equal(steps.length, 22);
    await verifyUsersAccess({ ...ui, admin, secondAdmin, owner, adminPassword, jf });
    assert.deepEqual(errors, []);
    run.write("ui-result.json", { passed: true, feature: "mu-users-roles", viewports: [1440, 320], steps: steps.length, browserErrors: errors, liveJellyfin: jf.image, ports: [run.manifest.apiPort, run.manifest.webPort, jf.port], revision: run.manifest.revision, dirtyIntegration: (await inspect(run.manifest, run.root)).dirty });
  } catch (error) {
    for (let index = 0; index < contexts.length; index++) for (const page of contexts[index].pages()) await save(page, `failure-context-${index}`).catch(() => {});
    run.write("ui-failure.json", { message: error.message, stack: error.stack }); throw error;
  } finally { await ui.close(); }
}